    public async Task<Attendance> BookClientAsync(string sessionId, string clientId, string? packageInstanceId)
    {
        var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
        if (session == null) throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found");

        // P4-S02 — Typed business exception so the frontend can branch on the
        // code and render the "Join waitlist" CTA instead of a generic toast.
        if (session.CurrentBookings >= session.Capacity)
            throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "Class is at full capacity.");

        var existing = await _attendances.Find(a => a.CalendarSessionId == sessionId && a.ClientId == clientId && a.Status != "CANCELLED" && a.Status != "LATE_CANCEL" && a.Status != "RESCHEDULED").FirstOrDefaultAsync();
        if (existing != null) throw new BusinessRuleException("BOOKING.ALREADY_BOOKED", "Client already booked for this session.");

        var attendance = new Attendance
        {
            CalendarSessionId = sessionId,
            ClientId = clientId,
            PackageInstanceId = packageInstanceId,
            Status = "BOOKED",
            BookedAt = DateTime.UtcNow,
            BookingReference = GenerateBookingReference(),
            BookingSource = "ADMIN"
        };
        // Atomically claim the seat before persisting so concurrent books can't overbook.
        if (!await TryClaimSessionCapacityAsync(sessionId, 1))
            throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "Class is at full capacity.");
        try
        {
            await _attendances.InsertOneAsync(attendance);
        }
        catch
        {
            await ReleaseSessionCapacityAsync(sessionId, 1);
            throw;
        }

        // P5-PWA — staff booked a client in (credit book); notify like any booking.
        FireAndForgetManualBookingPush(attendance, session);

        return attendance;
    }

