import { db } from "../lib/db";

const BOARD = "cmsavfvil000hhla4nlpuyge6";
const IN_PROGRESS = "cmsavfvin000khla4anofdbxt";
const REVIEW = "cmsavfvin000lhla47zkp8n9f";

const description = `Send the client a booking-confirmation email when a booking is made **manually** by a receptionist/staff in the backend. Previously only the online self-service path emailed the client.`;

const comment = `**Gap**
Only ONLINE self-service bookings and reschedules emailed the client a confirmation. A booking created MANUALLY at the desk never did.

Traced every booking-create path in \`SoulPilates.Services/SchedulingService.cs\`:
- \`ReserveSpotAsync\` (BookingSource=ONLINE) creates a **RESERVED** row and does NOT email — the online confirmation is sent by \`PaymentService.FireAndForgetBookingEmail\` at the RESERVED→BOOKED transition (Stripe / credit / zero-amount checkout).
- \`AdminRescheduleBookingAsync\` and \`CustomerAuthService\` reschedule paths already email.
- The three MANUAL create paths create a **BOOKED** row directly and never touch PaymentService, so they were the only routes that never emailed the client:
  - \`BookClientAsync\` — staff credit book (BookingSource=ADMIN)
  - \`WalkInCheckoutAsync\` — POS walk-in sale (BookingSource=WALK_IN)
  - \`AdminAddStudentAsync\` — admin/instructor add-to-session (BookingSource=WALK_IN)

**What changed** (1 file: \`SoulPilates.Services/SchedulingService.cs\`, +59 lines)
- New helper \`FireAndForgetManualBookingEmail(attendance, session)\` — fire-and-forget, guarded on a non-empty client email. \`BookClientAsync\`/\`AdminAddStudentAsync\` only store the clientId, so it resolves email + name from the Client record when the attendance doesn't carry them. It fires the exact same \`SendBookingConfirmationAsync(...)\` call \`CustomerAuthService\` uses (same 8 args).
- Wired into all three manual create paths, right after the existing \`FireAndForgetManualBookingPush\` call.

**No double-send guarantee**
Online bookings are RESERVED first and emailed by PaymentService at the RESERVED→BOOKED transition — they never flow through \`BookClientAsync\`/\`WalkInCheckoutAsync\`/\`AdminAddStudentAsync\`. The manual methods create BOOKED rows directly and only email there. So online customers still get exactly ONE email; manual bookings now also get one. (\`SplitBookingAsync\` — which just redistributes seats of an already-created booking to extra named guests — was intentionally left out of scope.)

**Staging deploy status — DONE (staging only, prod untouched)**
- Branch \`feature/manual-booking-confirmation-email\` built with \`docker build -t soulpilates/backend:staging -f SoulPilates.API/Dockerfile .\` → **build succeeded** (compile clean, warnings only). This is the compile verification of the new code path.
- Recreated ONLY \`soulpilates-staging-backend\` (\`docker compose -f docker-compose.staging.yml --env-file staging.env up -d --no-deps backend\`). Container is up and healthy — logs show "Application started / Now listening on http://[::]:8080".
- \`soulpilates-prod-backend\` and all other prod/prod.env/prod DB left completely untouched (prod backend still "Up 3 hours" on \`:latest\`). Prod source dir restored to \`main\`, clean.
- Staging SMTP runs in TestMode by default (redirects, never mails real customers), so a manual booking on staging is safe to trigger.

**Manual test the user can run on staging** (optional confidence check)
Log into staging admin, add a client (with an email) to a class via the desk "Add student" / POS walk-in / credit-book flow, then confirm a booking-confirmation email attempt appears (staging EmailLogs / redirected test inbox). Also make one ONLINE booking and confirm it still sends exactly one (no regression). NOTE: I did NOT run this end-to-end — reading the staging admin password from staging.env was blocked by the environment's command classifier, so I stopped at build-succeeded + container-healthy rather than working around it.

**To ship to PRODUCTION (needs owner approval)**
1. Merge \`feature/manual-booking-confirmation-email\` → \`main\` (PR: github.com/santino1233/soulpilatescrm).
2. Build the prod image: \`docker build -t soulpilates/backend:latest -f SoulPilates.API/Dockerfile .\` from \`main\`.
3. Recreate ONLY the prod backend: \`cd /opt/soulpilates && docker compose -f docker-compose.prod.yml --env-file prod.env up -d --no-deps backend\`.
4. Verify prod backend healthy; do one manual desk booking with a real client email and confirm they receive the confirmation.

Branch: **feature/manual-booking-confirmation-email** (pushed, commit 28b0f7a).`;

async function main() {
  const maxIp = await db.card.aggregate({ where: { columnId: IN_PROGRESS }, _max: { position: true } });
  const pos = (maxIp._max.position ?? -1) + 1;

  const card = await db.card.create({
    data: {
      boardId: BOARD,
      columnId: IN_PROGRESS,
      title: "Manual booking confirmation email",
      description,
      type: "FEATURE",
      priority: "HIGH",
      assignee: "Claude",
      position: pos,
    },
  });
  console.log("Created card in In progress:", card.id);

  // Move to Review (append at end of Review column)
  const maxRev = await db.card.aggregate({ where: { columnId: REVIEW }, _max: { position: true } });
  const revPos = (maxRev._max.position ?? -1) + 1;
  await db.card.update({ where: { id: card.id }, data: { columnId: REVIEW, position: revPos } });
  console.log("Moved card to Review, pos", revPos);

  const c = await db.cardComment.create({
    data: { cardId: card.id, authorName: "Claude", body: comment },
  });
  console.log("Comment added:", c.id);
  console.log("CARD_ID=" + card.id);
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

